priority_queue<int, vector<int>, greater<int>> high;       // MIN-heap (high half)

void addNum(int x) {
    low.push(x);
    high.push(low.top()); low.pop();                       // rebalance up
    if (high.size() > low.size()) { low.push(high.top()); high.pop(); }
}
double findMedian() {
    return low.size() > high.size() ? low.top() : (low.top() + high.top()) / 2.0;
